/* Locale metadata: display names, speech tags, direction */
const LOCALES = {
  en: { code: 'en', name: 'English', native: 'English', dir: 'ltr', speech: 'en-US', hint: 'EN' },
  hi: { code: 'hi', name: 'Hindi', native: 'हिन्दी', dir: 'ltr', speech: 'hi-IN', hint: 'HI' },
  ta: { code: 'ta', name: 'Tamil', native: 'தமிழ்', dir: 'ltr', speech: 'ta-IN', hint: 'TA' },
  ar: { code: 'ar', name: 'Arabic', native: 'العربية', dir: 'rtl', speech: 'ar-SA', hint: 'AR' }
};
const LOCALE_ORDER = ['en', 'hi', 'ta', 'ar'];

let currentLang = 'en';

function detectLang() {
  try {
    const saved = localStorage.getItem('argon.lang');
    if (saved && LOCALES[saved]) return saved;
  } catch (e) { /* storage blocked */ }
  const nav = (navigator.languages || [navigator.language || 'en'])
    .map((l) => String(l).toLowerCase().split('-')[0])
    .find((l) => LOCALES[l]);
  return nav || 'en';
}

function t(key, vars) {
  const pack = I18N[currentLang] || I18N.en;
  let s = pack[key];
  if (s === undefined) s = I18N.en[key];
  if (s === undefined) return key;
  if (vars) {
    for (const k in vars) s = s.split('{' + k + '}').join(String(vars[k]));
  }
  return s;
}

/** Pick the right element of a [en, hi, ta, ar] tuple (or a {en,hi,ta,ar} map). */
function t4(tuple, vars) {
  if (tuple && !Array.isArray(tuple) && typeof tuple === 'object') {
    tuple = [tuple.en, tuple.hi, tuple.ta, tuple.ar];
  }
  if (!Array.isArray(tuple)) return tuple;
  const idx = LOCALE_ORDER.indexOf(currentLang);
  const raw = tuple[idx !== -1 ? idx : 0];
  if (typeof raw !== 'string') return raw;
  if (vars) {
    for (const k in vars) raw = raw.split('{' + k + '}').join(String(vars[k]));
  }
  return raw;
}

function applyLangToDocument(lang) {
  currentLang = lang;
  const loc = LOCALES[lang];
  document.documentElement.setAttribute('lang', lang);
  document.documentElement.setAttribute('dir', loc.dir);
  document.body.classList.toggle('rtl', loc.dir === 'rtl');
}

/** Walk the DOM and replace every [data-i18n] text node with its translation. */
function translateDOM(root) {
  (root || document).querySelectorAll('[data-i18n]').forEach((el) => {
    el.textContent = t(el.getAttribute('data-i18n'));
  });
  (root || document).querySelectorAll('[data-i18n-ph]').forEach((el) => {
    el.setAttribute('placeholder', t(el.getAttribute('data-i18n-ph')));
  });
}
